H.background();
const A = P.A, w = P.w;
const pos = tt => A * Math.sin(w * tt);
const vel = tt => A * w * Math.cos(w * tt);
const acc = tt => -A * w * w * Math.sin(w * tt);
const tMax = 6.2832 / Math.max(w, 0.2);
const now = (t * 0.6) % tMax;
const colW = H.W - 200;
const ph = (H.H - 70) / 3;
const ymax = A * Math.max(1, w, w * w) * 1.15 + 0.1;
const panel = (yTop, fn, col, label) => {
  const view = H.plot2d({ xMin: 0, xMax: tMax, yMin: -ymax, yMax: ymax,
    box: { x: 60, y: yTop, w: colW, h: ph - 18 } });
  view.grid(); view.axes();
  view.fn(fn, { color: col, width: 3 });
  view.dot(now, fn(now), { r: 6, fill: col });
  view.line(now, -ymax, now, ymax, { color: H.colors.grid, width: 1, dash: [3, 3] });
  H.text(label + " = " + fn(now).toFixed(2), 70, yTop + 4, { color: col, size: 13, weight: 700 });
};
panel(54,            pos, H.colors.accent,  "x(t)");
panel(54 + ph,       vel, H.colors.accent2, "v(t)");
panel(54 + 2 * ph,   acc, H.colors.violet,  "a(t)");
const px = H.W - 130, mid = H.H / 2;
H.line(px, 70, px, H.H - 16, { color: H.colors.grid, width: 1 });
const scale = ph * 0.7 / ymax;
const py = mid - pos(now) * scale;
H.circle(px, py, 9, { fill: H.colors.accent });
H.arrow(px, py, px, py - vel(now) * scale, { color: H.colors.accent2, width: 3 });
H.text("particle", px - 20, 54, { color: H.colors.sub, size: 12 });
H.text("Position -> Velocity -> Acceleration", 24, 28, { color: H.colors.ink, size: 18, weight: 700 });
H.text("t = " + now.toFixed(2) + "s   v is slope of x,  a is slope of v", 320, 28, { color: H.colors.sub, size: 13 });
